Below is a complete, ready‑to‑copy Kotlin recipe that does the same thing on Android that `maplibregl.addProtocol()` does on the web.

### TL;DR
* **MapLibre‑Android** does not expose a `addProtocol` API, but every network request that the SDK makes goes through a pluggable **`HttpClient`** (or the older **`Network`** interface).  
* By installing your own `HttpClient` you can look at the URL, recognise the `vault://…` scheme, decrypt the tile that lives in your encrypted blob and return the raw bytes to the SDK.  
* After the client is installed you can keep the style JSON exactly the same as on the web:

```json
{
  "version": 8,
  "sources": {
    "my‑tiles": {
      "type": "vector",
      "tiles": ["vault://tiles/{z}/{x}/{y}"],
      "minzoom": 0,
      "maxzoom": 14
    }
  },
  "layers": [ … ]
}
```

---

## 1. The hook you need – `HttpClient`

`MapLibre.getInstance(context).setHttpClient(customClient)` tells the SDK to use **your** `HttpClient` for *every* HTTP‑like request (including custom schemes).  
`HttpClient` is a tiny interface:

```kotlin
interface HttpClient {
    fun newCall(request: Request): Call
}
```

You can implement it with a regular **OkHttp** client and add an **interceptor** that catches the `vault://` URLs.

### 2. Full Kotlin implementation

```kotlin
package com.example.maplibrevault

import android.content.Context
import android.net.Uri
import com.mapbox.mapboxsdk.MapLibre
import com.mapbox.mapboxsdk.http.HttpClient
import okhttp3.*
import okio.Buffer
import okio.Source
import okio.buffer
import okio.source
import java.io.File
import java.io.IOException
import java.util.concurrent.TimeUnit

/**
 * 1️⃣  Install this client **once**, before you create the MapView.
 *    (e.g. in Application.onCreate() or the Activity that hosts the map)
 */
fun installVaultHttpClient(context: Context) {
    // -----------------------------------------------------------------
    // 1️⃣  Build a normal OkHttpClient – you can keep all your usual
    //     time‑outs, cache, logging, etc.
    // -----------------------------------------------------------------
    val okHttp = OkHttpClient.Builder()
        .connectTimeout(15, TimeUnit.SECONDS)
        .readTimeout(30, TimeUnit.SECONDS)
        .writeTimeout(15, TimeUnit.SECONDS)
        // -----------------------------------------------------------------
        // 2️⃣  Add the interceptor that knows how to handle "vault://"
        // -----------------------------------------------------------------
        .addInterceptor(VaultInterceptor(context))
        .build()

    // -----------------------------------------------------------------
    // 3️⃣  Wrap the OkHttpClient in a MapLibre HttpClient implementation
    // -----------------------------------------------------------------
    val mapLibreClient = object : HttpClient {
        override fun newCall(request: Request): Call = okHttp.newCall(request)
    }

    // -----------------------------------------------------------------
    // 4️⃣  Register it with the SDK – **must be done before** any
    //     MapView/MapboxMap is created.
    // -----------------------------------------------------------------
    MapLibre.getInstance(context).setHttpClient(mapLibreClient)
}

/**
 * Interceptor that recognises the custom scheme, loads the encrypted tile,
 * decrypts it and returns a synthetic HTTP 200 response that contains the
 * raw protobuf bytes.
 */
private class VaultInterceptor(
    private val ctx: Context
) : Interceptor {

    // -----------------------------------------------------------------
    // Change these to match your own storage layout / encryption key.
    // -----------------------------------------------------------------
    private val encryptedBlobFile = File(ctx.filesDir, "tiles_blob.enc")
    private val encryptionKey = /* your 256‑bit key */ ByteArray(32) { 0 }

    override fun intercept(chain: Interceptor.Chain): Response {
        val request = chain.request()
        val url = request.url.toString()

        // -------------------------------------------------------------
        // Only handle our custom scheme – everything else falls through
        // to the normal network stack.
        // -------------------------------------------------------------
        if (!url.startsWith("vault://")) {
            return chain.proceed(request)
        }

        // -------------------------------------------------------------
        // Parse z / x / y from the URL.
        // -------------------------------------------------------------
        val uri = Uri.parse(url)
        // Expected format: vault://tiles/{z}/{x}/{y}
        val pathSegments = uri.pathSegments
        if (pathSegments.size < 3) {
            return errorResponse(request, 400, "Invalid vault URL")
        }
        val z = pathSegments[0].toInt()
        val x = pathSegments[1].toInt()
        val y = pathSegments[2].toInt()

        // -------------------------------------------------------------
        // 1️⃣  Load the encrypted slice that contains the requested tile.
        // 2️⃣  Decrypt it.
        // 3️⃣  Return the raw bytes.
        // -------------------------------------------------------------
        return try {
            val encryptedTile = readEncryptedTile(z, x, y)
            val plainTile = decryptTile(encryptedTile)

            // Build a synthetic HTTP response that MapLibre will treat as a
            // normal tile fetch.
            Response.Builder()
                .request(request)
                .protocol(Protocol.HTTP_1_1)
                .code(200)                     // OK
                .message("OK")
                .body(
                    plainTile.toResponseBody(
                        "application/x-protobuf".toMediaType()
                    )
                )
                .addHeader("Content-Type", "application/x-protobuf")
                .build()
        } catch (e: Exception) {
            // Anything that goes wrong should be reported as a 500 so the SDK
            // can retry / fall back.
            errorResponse(request, 500, e.localizedMessage ?: "Tile error")
        }
    }

    /** Helper to create a minimal error response */
    private fun errorResponse(request: Request, code: Int, msg: String): Response {
        return Response.Builder()
            .request(request)
            .protocol(Protocol.HTTP_1_1)
            .code(code)
            .message(msg)
            .body("".toResponseBody(null))
            .build()
    }

    /** -----------------------------------------------------------------
     *  YOUR IMPLEMENTATION BELOW – how you locate the encrypted tile inside
     *  the blob and how you decrypt it.
     * ----------------------------------------------------------------- */
    private fun readEncryptedTile(z: Int, x: Int, y: Int): ByteArray {
        // Example: the blob is a simple concatenation of tiles indexed by a
        // deterministic offset. Replace with your own indexing logic.
        // -------------------------------------------------------------
        // For demo purposes we just read the whole file – in a real app you
        // would seek to the correct offset.
        // -------------------------------------------------------------
        return encryptedBlobFile.readBytes()
    }

    private fun decryptTile(encrypted: ByteArray): ByteArray {
        // Replace this with your real crypto (AES‑GCM, ChaCha20‑Poly1305, …)
        // The example below just returns the input (no encryption).
        // -------------------------------------------------------------
        // Example using javax.crypto (API 23+):
        // -------------------------------------------------------------
        // val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        // val spec = GCMParameterSpec(128, iv)   // iv must be stored per‑tile
        // cipher.init(Cipher.DECRYPT_MODE, SecretKeySpec(encryptionKey, "AES"), spec)
        // return cipher.doFinal(encrypted)
        // -------------------------------------------------------------
        return encrypted   // <-- remove this line when you add real crypto
    }
}
```

