        // -----------------------------------------------------------------
        mapView.getMapAsync { mapLibreMap: MapLibreMap ->

            // -----------------------------------------------------------------
            // 2️⃣  Load a style (you can use any style you like)
            // -----------------------------------------------------------------
            mapLibreMap.setStyle(Style.Builder().fromUri(Style.MAPBOX_STREETS)) { style ->

                // -----------------------------------------------------------------
                // 3️⃣  Add the raster‑DEM source
                // -----------------------------------------------------------------
                val demSource = RasterDemSource(
                    "dem",                     // <-- source id (must match the one you use later)
                    "https://example.com/terrain.json" // <-- URL to the TileJSON / .json descriptor
                )
                style.addSource(demSource)

                // -----------------------------------------------------------------
                // 4️⃣  Enable terrain and set the exaggeration
                // -----------------------------------------------------------------
                val terrain = Terrain.Builder()
                    .sourceId("dem")          // <-- the id of the source we just added
                    .exaggeration(1.5)        // <-- 1.5× vertical exaggeration
                    .build()

                style.setTerrain(terrain)

                // (optional) you can later read / change the exaggeration like this:
                // style.getTerrain()?.exaggeration = 2.0f
            }
        }
    }

    // -----------------------------------------------------------------
    // Boiler‑plate lifecycle forwarding – required for MapLibreMap
    // -----------------------------------------------------------------
    override fun onStart()        = super.onStart().also { mapView.onStart() }
    override fun onResume()       = super.onResume().also { mapView.onResume() }
    override fun onPause()        = super.onPause().also { mapView.onPause() }
    override fun onStop()         = super.onStop().also { mapView.onStop() }
    override fun onLowMemory()    = super.onLowMemory().also { mapView.onLowMemory() }
    override fun onDestroy()      = super.onDestroy().also { mapView.onDestroy() }
