## 4. Gotchas & Best‑Practice Tips

| Issue | What to watch for | How to solve / mitigate |
|-------|-------------------|--------------------------|
| **CORS / Cloudflare R2 public access** | If the bucket is

Below is a **complete, ready‑to‑copy TypeScript example** that

1. creates (or opens) an IndexedDB database called `TileCache`,
2. stores vector‑tile blobs (`ArrayBuffer`s) under the key `z/x/y`,
3. registers a **custom `cache://` protocol** with MapLibre GL JS,
4. lets a style reference tiles as `cache://tiles/{z}/{x}/{y}.pbf`.

You can drop the file into a normal web‑app (e.g. a Vite/React project) and it will work out‑of‑the‑box – no server needed.

---

## 1️⃣  IndexedDB helper (tiny wrapper)

```ts
// src/TileCache.ts
export interface TileKey {
  z: number;
  x: number;
  y: number;
}

/**
 * Tiny wrapper around IndexedDB that stores raw PBF tiles.
 *
 * The object store is called "tiles" and the primary key is the string
 *   `${z}/${x}/${y}`
 *
 * All methods return native Promises – no external library required.
 */
export class TileCache {
  private static DB_NAME = "TileCache";
  private static STORE_NAME = "tiles";
  private static DB_VERSION = 1;

  private db!: IDBDatabase;

  /** Open (or create) the DB – call once before any other method. */
  async open(): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const request = indexedDB.open(TileCache.DB_NAME, TileCache.DB_VERSION);

      request.onupgradeneeded = () => {
        const db = request.result;
        // key = "z/x/y"
        db.createObjectStore(TileCache.STORE_NAME);
      };

      request.onsuccess = () => {
        this.db = request.result;
        resolve();
      };

      request.onerror = () => reject(request.error);
    });
  }

  /** Build the string key used in the object store. */
  private static makeKey({ z, x, y }: TileKey): string {
    return `${z}/${x}/${y}`;
  }

  /** Store a tile (ArrayBuffer) in the cache. */
  async put(tile: TileKey, data: ArrayBuffer): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const tx = this.db.transaction(TileCache.STORE_NAME, "readwrite");
      const store = tx.objectStore(TileCache.STORE_NAME);
      store.put(data, TileCache.makeKey(tile));

      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  }

  /** Retrieve a tile. Returns `null` if the tile is not cached. */
  async get(tile: TileKey): Promise<ArrayBuffer | null> {
    return new Promise<ArrayBuffer | null>((resolve, reject) => {
      const tx = this.db.transaction(TileCache.STORE_NAME, "readonly");
      const store = tx.objectStore(TileCache.STORE_NAME);
      const request = store.get(TileCache.makeKey(tile));

      request.onsuccess = () => {
        // `undefined` means “not found”
        resolve(request.result ?? null);
      };
      request.onerror = () => reject(request.error);
    });
  }

  /** Optional: delete a tile (useful for debugging). */
  async delete(tile: TileKey): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const tx = this.db.transaction(TileCache.STORE_NAME, "readwrite");
      const store = tx.objectStore(TileCache.STORE_NAME);
      store.delete(TileCache.makeKey(tile));

      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  }
}
```

---

## 2️⃣  Register the `cache://` protocol with MapLibre

```ts
// src/map.ts
import maplibregl, { Map, RequestParameters, RequestResult } from "maplibre-gl";
import { TileCache, TileKey } from "./TileCache";

/**
 * Initialise the IndexedDB cache and register the protocol.
 *
 * The handler receives the URL that MapLibre would have fetched, e.g.
 *   cache://tiles/12/3456/7890.pbf
 *
 * MapLibre parses the URL and passes the *named* parameters (`z`, `x`, `y`,
 * `path`, `query`, …) to the handler.  We only need `z`, `x`, `y`.
 */
export async function initMap(container: string | HTMLElement): Promise<Map> {
  // -------------------------------------------------
  // 1️⃣  Open the IndexedDB cache (must be done once)
  // -------------------------------------------------
  const cache = new TileCache();
  await cache.open();

  // -------------------------------------------------
  // 2️⃣  Register the custom protocol
  // -------------------------------------------------
  // MapLibre's `addProtocol` expects a function that returns either:
  //   - a Promise that resolves to { data: ArrayBuffer }
  //   - or an object { cancel: true } to tell MapLibre “skip this request”.
  // The second argument is an AbortController that we can honour if the
  // request is cancelled (e.g. user pans away before the DB read finishes).
  maplibregl.addProtocol("cache", async (params: RequestParameters, abortCtrl: AbortController) => {
    // `params` contains the parsed URL parts.
    // Example: cache://tiles/12/3456/7890.pbf  →  params.path = "tiles/12/3456/7890.pbf"
    // We only care about the numeric parts.
    const match = params.path?.match(/^tiles\/(\d+)\/(\d+)\/(\d+)\.pbf$/);
    if (!match) {
      // Not a tile we understand – let MapLibre try the next source (or error)
      return { cancel: true };
    }

    const [, zStr, xStr, yStr] = match;
    const tileKey: TileKey = {
      z: Number(zStr),
      x: Number(xStr),
      y: Number(yStr),
    };

    // -------------------------------------------------
    // 3️⃣  Look up the tile in IndexedDB
    // -------------------------------------------------
    const tileData = await cache.get(tileKey);

    // If the tile is missing we can either:
    //   a) return { cancel: true } → MapLibre will treat it as a 404 and
    //      show the “no data” background colour.
    //   b) fall back to a network URL (not shown here).
    if (!tileData) {
      return { cancel: true };
    }

    // -------------------------------------------------
    // 4️⃣  Return the raw PBF bytes to MapLibre
    // -------------------------------------------------
    // MapLibre expects the property name `data` to be an ArrayBuffer.
    // It will automatically set the correct MIME type (`application/x-protobuf`).
    const result: RequestResult = {
      data: tileData,
    };
    return result;
  });

  // -------------------------------------------------
  // 5️⃣  Create the map – the style can now use cache:// URLs
  // -------------------------------------------------
  const map = new maplibregl.Map({
    container,
    style: {
      version: 8,
      sources: {
        // Example source that points to the custom protocol
        "my‑vector‑tiles": {
          type: "vector",
          // The `{z}/{x}/{y}` placeholders are replaced by MapLibre before the request.
          // The `.pbf` suffix is required for vector tiles.
          tiles: ["cache://tiles/{z}/{x}/{y}.pbf"],
          // Optional: set a maxzoom that matches the data you stored.
          maxzoom: 14,
        },
      },
      layers: [
        {
          id: "water",
          type: "fill",
          source: "my‑vector‑tiles",
          "source-layer": "water", // <-- name of the layer inside the PBF
          paint: { "fill-color": "#a0c8f0" },
        },
        // …add more layers as you like
      ],
    },
    center: [0, 0],
    zoom: 2,
  });

  return map;
}
```

> **What the code does**
> * Opens (or creates) an IndexedDB database called **TileCache**.
> * Registers a **`cache://`** protocol that:
>   1. Parses the URL to extract `z/x/y`.
>   2. Looks up the tile in IndexedDB.
>   3. Returns the raw `ArrayBuffer` to MapLibre, or cancels the request if the tile is missing.
> * The map style can now reference tiles with `cache://tiles/{z}/{x}/{y}.pbf`.

