## 3️⃣  Populating the cache (optional helper)

You’ll usually want a way to **download tiles once** (e.g. from a remote server) and store them locally.  
Below is a tiny utility that fetches a tile from a regular HTTP source and writes it into the cache.

```ts
// src/populateCache.ts
import { TileCache, TileKey } from "./TileCache";

/**
 * Download a single tile from a remote URL and store it in IndexedDB.
 *
 * @param remoteUrl   e.g. "https://example.com/tiles/{z}/{x}/{y}.pbf"
 * @param tile        {z,x,y}
 */
export async function fetchAndCacheTile(
  remoteUrl: string,
  tile: TileKey,
  cache: TileCache
): Promise<void> {
  const url = remoteUrl
    .replace("{z}", tile.z.toString())
    .replace("{x}", tile.x.toString())
    .replace("{y}", tile.y.toString());

  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Failed to fetch ${url}: ${response.status}`);
  }
  const arrayBuffer = await response.arrayBuffer();
  await cache.put(tile, arrayBuffer);
}

/**
 * Example: cache a whole zoom level (be careful – many tiles!).
 */
export async function cacheZoomLevel(
  remoteTemplate: string,
  z: number,
  cache: TileCache
): Promise<void> {
  const maxX = 2 ** z - 1;
  const maxY = 2 ** z - 1;

  const promises: Promise<void>[] = [];

  for (let x = 0; x <= maxX; x++) {
    for (let y = 0; y <= maxY; y++) {
      const tile: TileKey = { z, x, y };
      promises.push(fetchAndCacheTile(remoteTemplate, tile, cache));
    }
  }

  // Run in parallel but limit concurrency if you like (e.g. p-limit)
  await Promise.all(promises);
}
```

**How to use it**

```ts
import { TileCache } from "./TileCache";
import { cacheZoomLevel } from "./populateCache";

(async () => {
  const cache = new TileCache();
  await cache.open();

  // Example remote source – replace with your own tile server.
  const remoteTemplate = "https://tileserver.example.com/tiles/{z}/{x}/{y}.pbf";

  // Cache zoom level 12 (4096 tiles). Adjust as needed.
  await cacheZoomLevel(remoteTemplate, 12, cache);
  console.log("Zoom‑12 tiles cached!");
})();
```

> **Tip:** For large areas you’ll want a smarter strategy (e.g. only cache tiles that are actually displayed, or use a Service Worker). The code above is just a minimal illustration.

