## 1️⃣  IndexedDB wrapper – `TileCacheDB`

```ts
// TileCacheDB.ts
export interface TileKey {
  z: number;
  x: number;
  y: number;
}

/**
 * Tiny wrapper around IndexedDB that stores raw vector‑tile ArrayBuffers.
 * Keys are stored as the string `${z}/${x}/${y}`.
 */
export class TileCacheDB {
  private static readonly DB_NAME = "TileCache";
  private static readonly STORE_NAME = "tiles";
  private static readonly DB_VERSION = 1;

  private db!: IDBDatabase;

  /** Open (or create) the DB – must be awaited before any other method. */
  async open(): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const request = indexedDB.open(TileCacheDB.DB_NAME, TileCacheDB.DB_VERSION);

      request.onupgradeneeded = () => {
        const db = request.result;
        // Create an object store that uses the string key `${z}/${x}/${y}`
        db.createObjectStore(TileCacheDB.STORE_NAME);
      };

      request.onsuccess = () => {
        this.db = request.result;
        resolve();
      };

      request.onerror = () => reject(request.error);
    });
  }

  /** Build the string key used internally by IndexedDB. */
  private static makeKey({ z, x, y }: TileKey): string {
    return `${z}/${x}/${y}`;
  }

  /** Store a tile (ArrayBuffer) in the cache. */
  async putTile(key: TileKey, data: ArrayBuffer): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const tx = this.db.transaction(TileCacheDB.STORE_NAME, "readwrite");
      const store = tx.objectStore(TileCacheDB.STORE_NAME);
      const request = store.put(data, TileCacheDB.makeKey(key));

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  /** Retrieve a tile. Returns `null` if the tile is not cached. */
  async getTile(key: TileKey): Promise<ArrayBuffer | null> {
    return new Promise<ArrayBuffer | null>((resolve, reject) => {
      const tx = this.db.transaction(TileCacheDB.STORE_NAME, "readonly");
      const store = tx.objectStore(TileCacheDB.STORE_NAME);
      const request = store.get(TileCacheDB.makeKey(key));

      request.onsuccess = () => {
        // `request.result` is either an ArrayBuffer or undefined
        resolve(request.result ?? null);
      };
      request.onerror = () => reject(request.error);
    });
  }

  /** Optional: delete a tile (useful for debugging). */
  async deleteTile(key: TileKey): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const tx = this.db.transaction(TileCacheDB.STORE_NAME, "readwrite");
      const store = tx.objectStore(TileCacheDB.STORE_NAME);
      const request = store.delete(TileCacheDB.makeKey(key));

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }
}
```

