## 2️⃣  Register the `cache://` protocol with MapLibre

```ts
// map-protocol.ts
import maplibregl, { Map, RequestParameters } from "maplibre-gl";
import { TileCacheDB, TileKey } from "./TileCacheDB";

/**
 * Register a custom protocol named `cache` that reads tiles from IndexedDB.
 *
 * MapLibre will call the handler with a `RequestParameters` object that contains
 * the URL‑template placeholders (`{z}`, `{x}`, `{y}`) already substituted.
 *
 * The handler must return an object that either:
 *   - contains `data: ArrayBuffer` (the tile payload), or
 *   - contains `cancel: true` to tell MapLibre to fall back to its normal fetch.
 *
 * The `abortController` argument lets us abort a pending IndexedDB request if the
 * map decides it no longer needs the tile (e.g. fast pan/zoom). IndexedDB does not
 * have a native abort API, so we simply ignore the abort signal – MapLibre will
 * discard the result when it arrives.
 */
export async function registerCacheProtocol(map: Map, db: TileCacheDB): Promise<void> {
  // Ensure the DB is ready before we start handling requests.
  await db.open();

  // The protocol name is the part before the colon in the URL: `cache://…`
  map.addProtocol("cache", async (params: RequestParameters, abortController: AbortController) => {
    // `params.url` looks like: "cache://tiles/12/3456/7890.pbf"
    // Strip the scheme and the optional leading slash.
    const urlPath = params.url.replace(/^cache:\/\//, "");

    // Expected pattern: "tiles/{z}/{x}/{y}.pbf"
    const match = urlPath.match(/^tiles\/(\d+)\/(\d+)\/(\d+)\.pbf$/);
    if (!match) {
      console.warn(`cache protocol received unexpected URL: ${params.url}`);
      return { cancel: true };
    }

    const [, zStr, xStr, yStr] = match;
    const key: TileKey = {
      z: Number(zStr),
      x: Number(xStr),
      y: Number(yStr),
    };

    // Try to read the tile from IndexedDB.
    const tileData = await db.getTile(key);

    if (tileData) {
      // Success – give MapLibre the raw PBF bytes.
      return { data: tileData };
    }

    // Tile not in cache → let MapLibre fall back to its normal HTTP fetch.
    // (You could also trigger a background download here if you want.)
    return { cancel: true };
  });
}
```

