## 3️⃣  Putting it all together – a minimal app

```ts
// index.ts (or any entry point you bundle)
import maplibregl from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css"; // if you use a bundler that can import CSS
import { TileCacheDB } from "./TileCacheDB";
import { registerCacheProtocol } from "./map-protocol";

/* --------------------------------------------------------------
   1️⃣  Initialise the IndexedDB cache
   -------------------------------------------------------------- */
const tileCache = new TileCacheDB();

/* --------------------------------------------------------------
   2️⃣  Create the MapLibre map
   -------------------------------------------------------------- */
const map = new maplibregl.Map({
  container: "map", // <-- the id of the <div id="map"></div> in your HTML
  style: {
    version: 8,
    sources: {
      // The source uses the custom `cache://` scheme.
      osm: {
        type: "vector",
        // The URL pattern can be any string; MapLibre will replace {z}/{x}/{y}
        // before calling the protocol handler.
        tiles: ["cache://tiles/{z}/{x}/{y}.pbf"],
        // Optional: a fallback URL in case the tile is missing from the cache.
        // MapLibre will try the fallback *after* the protocol returns `cancel:true`.
        // (You can also omit this and let the protocol itself fetch & store.)
        // Example fallback (commented out):
        // url: "https://tile.openstreetmap.org/{z}/{x}/{y}.pbf"
      },
    },
    layers: [
      {
        id: "water",
        type: "fill",
        source: "osm",
        "source-layer": "water",
        paint: { "fill-color": "#a0c8f0" },
      },
      // add more layers you need …
    ],
  },
  center: [0, 0],
  zoom: 2,
});

/* --------------------------------------------------------------
   3️⃣  Register the custom protocol (must happen after map creation)
   -------------------------------------------------------------- */
registerCacheProtocol(map, tileCache).catch((e) => console.error("Protocol registration failed:", e));

/* --------------------------------------------------------------
   4️⃣  (Optional) Pre‑load a few tiles into the cache.
       In a real app you would probably download tiles on‑the‑fly
       and store them as the user pans/zooms.
   -------------------------------------------------------------- */
async function preloadSomeTiles() {
  // Example remote source – you can replace this with any vector‑tile endpoint.
  const remoteBase = "https://tile.openstreetmap.org";

  // Choose a small set of tiles to pre‑populate.
  const tilesToCache: TileKey[] = [
    { z: 2, x: 1, y: 1 },
    { z: 2, x: 2, y: 1 },
    { z: 2, x: 1, y: 2 },
    { z: 2, x: 2, y: 2 },
  ];

  for (const key of tilesToCache) {
    const url = `${remoteBase}/${key.z}/${key.x}/${key.y}.pbf`;
    try {
      const resp = await fetch(url);
      if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
      const arrayBuffer = await resp.arrayBuffer();
      await tileCache.putTile(key, arrayBuffer);
      console.log(`Cached tile ${key.z}/${key.x}/${key.y}`);
    } catch (err) {
      console.warn(`Failed to cache ${url}:`, err);
    }
  }
}

/* --------------------------------------------------------------
   5️⃣  Kick off the preload (you can comment this out if you
       prefer to fill the cache lazily later).
   -------------------------------------------------------------- */
preloadSomeTiles().catch(console.error);
```

