## 1️⃣  IndexedDB helper (tiny wrapper)

```ts
// src/TileCache.ts
export interface TileKey {
  z: number;
  x: number;
  y: number;
}

/**
 * Tiny wrapper around IndexedDB that stores raw PBF tiles.
 *
 * The object store is called "tiles" and the primary key is the string
 *   `${z}/${x}/${y}`
 *
 * All methods return native Promises – no external library required.
 */
export class TileCache {
  private static DB_NAME = "TileCache";
  private static STORE_NAME = "tiles";
  private static DB_VERSION = 1;

  private db!: IDBDatabase;

  /** Open (or create) the DB – call once before any other method. */
  async open(): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const request = indexedDB.open(TileCache.DB_NAME, TileCache.DB_VERSION);

      request.onupgradeneeded = () => {
        const db = request.result;
        // key = "z/x/y"
        db.createObjectStore(TileCache.STORE_NAME);
      };

      request.onsuccess = () => {
        this.db = request.result;
        resolve();
      };

      request.onerror = () => reject(request.error);
    });
  }

  /** Build the string key used in the object store. */
  private static makeKey({ z, x, y }: TileKey): string {
    return `${z}/${x}/${y}`;
  }

  /** Store a tile (ArrayBuffer) in the cache. */
  async put(tile: TileKey, data: ArrayBuffer): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const tx = this.db.transaction(TileCache.STORE_NAME, "readwrite");
      const store = tx.objectStore(TileCache.STORE_NAME);
      store.put(data, TileCache.makeKey(tile));

      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  }

  /** Retrieve a tile. Returns `null` if it is not cached. */
  async get(tile: TileKey): Promise<ArrayBuffer | null> {
    return new Promise<ArrayBuffer | null>((resolve, reject) => {
      const tx = this.db.transaction(TileCache.STORE_NAME, "readonly");
      const store = tx.objectStore(TileCache.STORE_NAME);
      const request = store.get(TileCache.makeKey(tile));

      request.onsuccess = () => {
        // `undefined` means “not found”
        resolve(request.result ?? null);
      };
      request.onerror = () => reject(request.error);
    });
  }

  /** Optional: delete a tile (e.g. for cache‑eviction). */
  async delete(tile: TileKey): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const tx = this.db.transaction(TileCache.STORE_NAME, "readwrite");
      const store = tx.objectStore(TileCache.STORE_NAME);
      store.delete(TileCache.makeKey(tile));

      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  }
}
```

