## 2️⃣  Register the `cache://` protocol with MapLibre

```ts
// src/map.ts
import maplibregl, { Map, RequestParameters, RequestResult } from "maplibre-gl";
import { TileCache, TileKey } from "./TileCache";

/**
 * Initialise the IndexedDB cache and then create the map.
 * The function returns the ready `Map` instance.
 */
export async function initMap(containerId: string): Promise<Map> {
  // -------------------------------------------------
  // 1️⃣  Open the IndexedDB cache (must be done once)
  // -------------------------------------------------
  const cache = new TileCache();
  await cache.open();

  // -------------------------------------------------
  // 2️⃣  Register the custom protocol
  // -------------------------------------------------
  /**
   * MapLibre will call this handler for every URL that starts with
   *   `cache://`.
   *
   * `params` contains the URL parts that MapLibre has already expanded,
   *   e.g. for `cache://tiles/12/3456/7890.pbf` you get:
   *   {
   *     url: "cache://tiles/12/3456/7890.pbf",
   *     // the following are extracted from the URL pattern:
   *     z: 12,
   *     x: 3456,
   *     y: 7890,
   *     // any other query‑string params would also be present
   *   }
   *
   * The handler must return a `Promise<RequestResult>`:
   *   - `{ data: ArrayBuffer }`  → tile is served from cache
   *   - `{ cancel: true }`       → tell MapLibre to fall back to its normal
   *                               network request (or to report an error)
   */
  maplibregl.addProtocol("cache", async (params: RequestParameters, abortCtrl: AbortController): Promise<RequestResult> => {
    // 1️⃣  Extract the tile coordinates from the URL.
    //    MapLibre already parses `{z}/{x}/{y}` placeholders for us.
    const { z, x, y } = params as unknown as TileKey; // cast for convenience

    // 2️⃣  Try to read the tile from IndexedDB.
    const tileData = await cache.get({ z, x, y });

    // 3️⃣  If we have it, return it.
    if (tileData) {
      return { data: tileData };
    }

    // 4️⃣  If not cached we can either:
    //    a) let MapLibre try the normal network (by returning `cancel: true`);
    //    b) fetch it ourselves, store it, then return it.
    //    Below we do (b) – a simple “populate‑on‑miss” strategy.

    // Build the *real* URL that points to the remote source.
    // You can change this to any public tile endpoint you like.
    const remoteUrl = `https://tileserver.example.com/tiles/${z}/${x}/${y}.pbf`;

    try {
      const response = await fetch(remoteUrl, { signal: abortCtrl.signal });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);

      const arrayBuffer = await response.arrayBuffer();

      // Store the freshly fetched tile for next time.
      // (Fire‑and‑forget – we don’t block the map rendering on the write.)
      cache.put({ z, x, y }, arrayBuffer).catch(console.error);

      return { data: arrayBuffer };
    } catch (err) {
      // If the fetch fails we tell MapLibre to cancel the request.
      // The map will render a “missing tile” placeholder.
      console.warn(`Failed to fetch tile ${z}/${x}/${y} from remote source`, err);
      return { cancel: true };
    }
  });

  // -------------------------------------------------
  // 3️⃣  Create the MapLibre map
  // -------------------------------------------------
  const map = new maplibregl.Map({
    container: containerId,
    style: {
      version: 8,
      sources: {
        // The source uses the custom protocol.
        "my‑vector‑source": {
          type: "vector",
          // Note the `.pbf` suffix – MapLibre expects binary protobuf.
          tiles: ["cache://tiles/{z}/{x}/{y}.pbf"],
          // Optional: set a maxzoom that matches your source.
          maxzoom: 14,
        },
      },
      layers: [
        {
          id: "my‑fill",
          type: "fill",
          source: "my‑vector‑source",
          "source-layer": "my_layer_name", // <-- change to your layer name
          paint: {
            "fill-color": "#88c0d0",
            "fill-opacity": 0.6,
          },
        },
      ],
    },
    center: [0, 0],
    zoom: 2,
  });

  // Wait for the style to load before returning.
  await new Promise<void>((resolve) => map.once("styledata", () => resolve()));

  return map;
}
```

### What the code does, step‑by‑step

| Step | What happens |
|------|--------------|
| **Open IndexedDB** | `TileCache.open()` creates (or upgrades) a DB with a single object store called `tiles`. |
| **Register protocol** | `maplibregl.addProtocol('cache', handler)` tells MapLibre “whenever you see a URL that starts with `cache://`, call *this* function instead of doing a normal HTTP fetch.” |
| **Handler logic** | 1️⃣ Extract `z/x/y` from the request parameters. <br>2️⃣ Look for a cached blob in IndexedDB. <br>3️⃣ If found → return `{data}` (MapLibre draws it). <br>4️⃣ If not found → fetch from a real remote server, store the result in IndexedDB, then return the data. |
| **Abort handling** | The `AbortController` passed by MapLibre is forwarded to the `fetch` call, so if the user pans away before the request finishes the network request is cancelled automatically. |
| **Style** | The style JSON references `cache://tiles/{z}/{x}/{y}.pbf`. MapLibre expands the placeholders and calls the protocol handler for each tile request. |

