## 4️⃣  Pre‑populating the cache (optional)

If you want to **seed** the cache ahead of time (e.g. during an offline‑first install), you can run a one‑off script that fetches a list of tiles and stores them:

```ts
// src/prepopulate.ts
import { TileCache } from "./TileCache";

async function prepopulate(tiles: TileKey[]) {
  const cache = new TileCache();
  await cache.open();

  for (const tile of tiles) {
    const url = `https://tileserver.example.com/tiles/${tile.z}/${tile.x}/${tile.y}.pbf`;
    try {
      const resp = await fetch(url);
      if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
      const data = await resp.arrayBuffer();
      await cache.put(tile, data);
      console.log(`Cached ${tile.z}/${tile.x}/${tile.y}`);
    } catch
